param([Parameter(Mandatory=$true)][string]$ObservationFile)
$ErrorActionPreference='Stop'
$taskRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'))
$taskBase=Join-Path $taskRoot 'docs\maintenance\2026-10-20\weekly-system-handoff-01'
$taskObservation=Get-Content -Raw -LiteralPath $ObservationFile | ConvertFrom-Json
if([int]$taskObservation.primary_used_percent -lt 100 -and $taskObservation.ordinary_usage_allowed -and [long]$taskObservation.reset_identity -eq 1792497266){throw 'No actual boundary observed'}
$taskKind=if([long]$taskObservation.reset_identity -ne 1792497266){'WINDOW_END'}elseif([int]$taskObservation.primary_used_percent -ge 100){'ACCOUNT_STOP'}else{'USAGE_DISALLOWED'}
$taskPath=Join-Path $taskBase ($taskKind+'.json')
if(Test-Path -LiteralPath $taskPath){throw 'Preserve existing boundary'}
$taskBoundary=[ordered]@{type=$taskKind;actual_observation=$taskObservation;scientific_work_stopped=$true;automatic_reset_continuation=$false;original_research_goal_complete=$false;goal_status_changed=$false;latest_full_raw_benchmark='2026-10-11';LMB_total_seconds=1073.9382182;original_LMB_cap_seconds=1800;all_prior_seals_preserved=$true}
[IO.File]::WriteAllText($taskPath,($taskBoundary|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
$taskEntry='October20 final continuation boundary '+$taskKind+': actual primary'+$taskObservation.primary_used_percent+'%/ordinaryAllowed='+$taskObservation.ordinary_usage_allowed+' with following '+$taskObservation.following_utc+', reset'+$taskObservation.reset_identity+'. Stop this continuation; no automatic reset resume. System mean target attained by experimental fixed-G (ATE0.648336m/ter0.446952%) versus KISS0.699689m/0.478614%; individual07ter/10rer protection failed and remaining-four ATE not universally better. Standard all-six B/G poses and reusable fixed-E0/anchor components delivered, complete-source/proof archives checked. Read docs/maintenance/2026-10-20/weekly-system-handoff-01/CURRENT_HANDOFF.md, REPORT.md and NEXT_STRATEGY_CN.md; later account supplement governs boundary. Original LMB total1073.9382182/1800s, no cap reset; old negatives/stops/seals preserved. Latest complete raw-system benchmark staysOct11; no new RAP increment, default/installed/production/Git/outreach/scheduler/goal-status action. Original research objective unresolved.'
$taskAgents=Join-Path $taskRoot 'AGENTS.md';$taskOld=[IO.File]::ReadAllBytes($taskAgents);$taskCut=[Array]::IndexOf($taskOld,[byte]10)+1;$taskInsert=[Text.Encoding]::UTF8.GetBytes("`n"+$taskEntry+"`n")
$taskNew=[byte[]]::new($taskOld.Length+$taskInsert.Length);[Array]::Copy($taskOld,0,$taskNew,0,$taskCut);[Array]::Copy($taskInsert,0,$taskNew,$taskCut,$taskInsert.Length);[Array]::Copy($taskOld,$taskCut,$taskNew,$taskCut+$taskInsert.Length,$taskOld.Length-$taskCut);[IO.File]::WriteAllBytes($taskAgents,$taskNew)
$taskPhase=Join-Path (Split-Path $taskBase) 'PHASE_RECORD.md';$taskPrior=[IO.File]::ReadAllBytes($taskPhase);$taskAppend=[Text.Encoding]::UTF8.GetBytes("`n`n# October20 final account boundary`n`n"+$taskEntry+"`n");$taskCombined=[byte[]]::new($taskPrior.Length+$taskAppend.Length);[Array]::Copy($taskPrior,0,$taskCombined,0,$taskPrior.Length);[Array]::Copy($taskAppend,0,$taskCombined,$taskPrior.Length,$taskAppend.Length);[IO.File]::WriteAllBytes($taskPhase,$taskCombined)
$taskFiles=[ordered]@{}
foreach($taskItem in @($taskPath,$ObservationFile,$taskAgents,$taskPhase,(Join-Path $taskBase 'CURRENT_HANDOFF.md'),(Join-Path $taskBase 'COST_FINAL_SUPPLEMENT.json'),(Join-Path $taskBase 'INTEGRATION_COMPLETE_CHECKS.json'),(Join-Path $taskBase 'FINAL_WINDOWS_PACKAGE_CHECKS.json'),(Join-Path $taskBase 'FINAL_DELIVERY_NOTES.md'),$PSCommandPath)){$taskFiles[$taskItem]=(Get-FileHash -LiteralPath $taskItem -Algorithm SHA256).Hash.ToLowerInvariant()}
$taskSeal=[ordered]@{type=$taskKind;files=$taskFiles;prior_AGENTS_sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($taskOld)).ToLowerInvariant();old_AGENTS_body_preserved=$true;old_phase_prefix_preserved=$true;historical_delivery_seals_rewritten=$false}
[IO.File]::WriteAllText((Join-Path $taskBase ($taskKind+'_SEAL.json')),($taskSeal|ConvertTo-Json -Depth 7),[Text.UTF8Encoding]::new($false))
[pscustomobject]@{boundary=$taskKind;actual_primary=$taskObservation.primary_used_percent;actual_ordinary_allowed=$taskObservation.ordinary_usage_allowed;old_records_preserved=$true} | ConvertTo-Json -Compress
